unint32 i;
adcs_vec3_t axes_n[3];
double raw[3];
double achieved_x = 0.0, achieved_y = 0.0, achieved_z = 0.0;
int any_limit = 0, missing = 0;

/* Disable: 重置 NORMAL 且 previous 清零 */
if (!wa_input.enable) {
    wa_state.mode = WA_NORMAL;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
    wa_state.previous_wheel_torque_nm[0] = 0.0;
    wa_state.previous_wheel_torque_nm[1] = 0.0;
    wa_state.previous_wheel_torque_nm[2] = 0.0;
    wa_output.mode = WA_NORMAL;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    wa_output.wheel_torque_nm[0] = 0.0;
    wa_output.wheel_torque_nm[1] = 0.0;
    wa_output.wheel_torque_nm[2] = 0.0;
    wa_output.achieved_torque_nm = (adcs_vec3_t){0, 0, 0};
    wa_output.residual_torque_nm = (adcs_vec3_t){0, 0, 0};
    wa_output.residual_norm_nm = 0.0;
    return;
}

/* 清零输出字段 */
wa_output.saturation_mask = 0U;
wa_output.slew_mask = 0U;
wa_output.unavailable_mask = 0U;
wa_output.wheel_torque_nm[0] = 0.0;
wa_output.wheel_torque_nm[1] = 0.0;
wa_output.wheel_torque_nm[2] = 0.0;
wa_output.achieved_torque_nm = (adcs_vec3_t){0, 0, 0};
wa_output.residual_torque_nm = (adcs_vec3_t){0, 0, 0};
wa_output.residual_norm_nm = 0.0;

/* 校验：计数/指针/mask */
if (wa_input.axis_count != 3U || wa_input.axes == NULL ||
    wa_input.requested_torque_nm == NULL ||
    !adcs_is_finite_vec3(wa_input.requested_torque_nm) ||
    (wa_input.available_mask & ~0x7U) != 0U) {
    wa_state.mode = WA_FAULT;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
    wa_state.previous_wheel_torque_nm[0] = 0.0;
    wa_state.previous_wheel_torque_nm[1] = 0.0;
    wa_state.previous_wheel_torque_nm[2] = 0.0;
    wa_output.mode = WA_FAULT;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    return;
}
{
    unint32 avail_count = 0U;
    for (i = 0U; i < 3U; i++)
        if ((wa_input.available_mask & (1U << i)) != 0U)
            avail_count++;
    if (avail_count < 2U) {
        wa_state.mode = WA_FAULT;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
        wa_state.previous_wheel_torque_nm[0] = 0.0;
        wa_state.previous_wheel_torque_nm[1] = 0.0;
        wa_state.previous_wheel_torque_nm[2] = 0.0;
        wa_output.mode = WA_FAULT;
        wa_output.clean_count = 0U;
        wa_output.restore_count = 0U;
        return;
    }
}
if (!(wa_config.release_cycles >= 1U && wa_config.release_cycles <= 20U &&
      wa_config.restore_cycles >= 1U && wa_config.restore_cycles <= 20U)) {
    wa_state.mode = WA_FAULT;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
    wa_state.previous_wheel_torque_nm[0] = 0.0;
    wa_state.previous_wheel_torque_nm[1] = 0.0;
    wa_state.previous_wheel_torque_nm[2] = 0.0;
    wa_output.mode = WA_FAULT;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    return;
}
for (i = 0U; i < 3U; i++) {
    if (!isfinite(wa_config.wheel_limit_nm[i]) || wa_config.wheel_limit_nm[i] <= 0.0 ||
        !isfinite(wa_config.max_wheel_slew_nm_per_cycle[i]) ||
        wa_config.max_wheel_slew_nm_per_cycle[i] <= 0.0 ||
        !isfinite(wa_state.previous_wheel_torque_nm[i]) ||
        !adcs_is_finite_vec3(&wa_input.axes[i]) ||
        adcs_vec3_normalize(&wa_input.axes[i], ADCS_EPS_NORM, &axes_n[i]) != ADCS_OK) {
        wa_state.mode = WA_FAULT;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
        wa_state.previous_wheel_torque_nm[0] = 0.0;
        wa_state.previous_wheel_torque_nm[1] = 0.0;
        wa_state.previous_wheel_torque_nm[2] = 0.0;
        wa_output.mode = WA_FAULT;
        wa_output.clean_count = 0U;
        wa_output.restore_count = 0U;
        return;
    }
    if ((wa_input.available_mask & (1U << i)) == 0U) {
        missing = 1;
    }
}
if (fabs(adcs_vec3_dot(&axes_n[0], &axes_n[1])) > ADCS_EPS_COLLINEAR ||
    fabs(adcs_vec3_dot(&axes_n[0], &axes_n[2])) > ADCS_EPS_COLLINEAR ||
    fabs(adcs_vec3_dot(&axes_n[1], &axes_n[2])) > ADCS_EPS_COLLINEAR) {
    wa_state.mode = WA_FAULT;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
    wa_state.previous_wheel_torque_nm[0] = 0.0;
    wa_state.previous_wheel_torque_nm[1] = 0.0;
    wa_state.previous_wheel_torque_nm[2] = 0.0;
    wa_output.mode = WA_FAULT;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    return;
}

/* 分配：不可用=0，可用 raw = -axis·requested */
for (i = 0U; i < 3U; i++) {
    if ((wa_input.available_mask & (1U << i)) == 0U) {
        raw[i] = 0.0;
        wa_output.unavailable_mask |= (1U << i);
    } else {
        raw[i] = -adcs_vec3_dot(&axes_n[i], wa_input.requested_torque_nm);
    }
}

/* magnitude limit + slew limit */
for (i = 0U; i < 3U; i++) {
    double t;
    if ((wa_input.available_mask & (1U << i)) == 0U) {
        wa_output.wheel_torque_nm[i] = 0.0;
        continue;
    }
    t = raw[i];
    if (fabs(t) > wa_config.wheel_limit_nm[i]) {
        t = copysign(wa_config.wheel_limit_nm[i], t);
        wa_output.saturation_mask |= (1U << i);
        any_limit = 1;
    }
    {
        double delta = t - wa_state.previous_wheel_torque_nm[i];
        double slew = wa_config.max_wheel_slew_nm_per_cycle[i];
        if (fabs(delta) > slew) {
            t = wa_state.previous_wheel_torque_nm[i] + copysign(slew, delta);
            wa_output.slew_mask |= (1U << i);
            any_limit = 1;
        }
    }
    wa_output.wheel_torque_nm[i] = t;
}

/* 重构 achieved */
for (i = 0U; i < 3U; i++) {
    achieved_x += axes_n[i].x * wa_output.wheel_torque_nm[i];
    achieved_y += axes_n[i].y * wa_output.wheel_torque_nm[i];
    achieved_z += axes_n[i].z * wa_output.wheel_torque_nm[i];
}
wa_output.achieved_torque_nm = (adcs_vec3_t){achieved_x, achieved_y, achieved_z};

/* residual */
wa_output.residual_torque_nm = adcs_vec3_sub(wa_input.requested_torque_nm,
                                             &wa_output.achieved_torque_nm);
wa_output.residual_norm_nm = adcs_vec3_norm(&wa_output.residual_torque_nm);

/* 模式机：missing 优先进入 DEGRADED；limit 优先于 health recovery */
if (wa_state.mode == WA_FAULT) {
    /* latch 保持 */
} else if (missing) {
    wa_state.mode = WA_DEGRADED;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
} else if (any_limit) {
    wa_state.mode = WA_LIMITED;
    wa_state.clean_count = 0U;
    wa_state.restore_count = 0U;
} else {
    /* 全部健康且无饱和 */
    if (wa_state.mode == WA_DEGRADED) {
        wa_state.mode = WA_RECOVERING;
        wa_state.restore_count = 1U;
        wa_state.clean_count = 0U;
        if (wa_config.restore_cycles <= 1U)
            wa_state.mode = WA_NORMAL;
    } else if (wa_state.mode == WA_RECOVERING) {
        if (wa_state.restore_count < 20U)
            wa_state.restore_count++;
        if (wa_state.restore_count >= wa_config.restore_cycles)
            wa_state.mode = WA_NORMAL;
    } else if (wa_state.mode == WA_LIMITED) {
        if (wa_state.clean_count < 20U)
            wa_state.clean_count++;
        if (wa_state.clean_count >= wa_config.release_cycles) {
            wa_state.mode = WA_NORMAL;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
        }
    } else {
        wa_state.mode = WA_NORMAL;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
    }
}

wa_state.previous_wheel_torque_nm[0] = wa_output.wheel_torque_nm[0];
wa_state.previous_wheel_torque_nm[1] = wa_output.wheel_torque_nm[1];
wa_state.previous_wheel_torque_nm[2] = wa_output.wheel_torque_nm[2];

wa_output.mode = wa_state.mode;
wa_output.clean_count = wa_state.clean_count;
wa_output.restore_count = wa_state.restore_count;

