    wa_output.mode = WA_FAULT;
    wa_output.clean_count = 0U;
    wa_output.restore_count = 0U;
    return;
}
for (i = 0U; i < 3U; i++) {
    if (!isfinite(wa_config.wheel_limit_nm[i]) || wa_config.wheel_limit_nm[i] <= 0.0 ||
        !isfinite(wa_config.max_wheel_slew_nm_per_cycle[i]) ||
        wa_config.max_wheel_slew_nm_per_cycle[i] <= 0.0 ||
        !isfinite(wa_state.previous_wheel_torque_nm[i]) ||
        !adcs_is_finite_vec3(&wa_input.axes[i]) ||
        adcs_vec3_normalize(&wa_input.axes[i], ADCS_EPS_NORM, &axes_n[i]) != ADCS_OK) {
        wa_state.mode = WA_FAULT;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
        wa_state.previous_wheel_torque_nm[0] = 0.0;
        wa_state.previous_wheel_torque_nm[1] = 0.0;
        wa_state.previous_wheel_torque_nm[2] = 0.0;
        wa_output.mode = WA_FAULT;
        wa_output.clean_count = 0U;
        wa_output.restore_count = 0U;
        return;
    }
    if ((wa_input.available_mask & (1U << i)) == 0U) {
        missing = 1;
    }
}
if (fabs(adcs_vec3_dot(&axes_n[0], &axes_n[1])) > ADCS_EPS_COLLINEAR ||
    fabs(adcs_vec3_dot(&axes_n[0], &axes_n[2])) > ADCS_EPS_COLLINEAR ||
    fabs(adcs_vec3_dot(&axes_n[1], &axes_n[2])) > ADCS_EPS_COLLINEAR) {
