for (i = 0U; i < 3U; i++) {
    achieved_x += axes_n[i].x * wa_output.wheel_torque_nm[i];
    achieved_y += axes_n[i].y * wa_output.wheel_torque_nm[i];
    achieved_z += axes_n[i].z * wa_output.wheel_torque_nm[i];
