            if (!isfinite(lmin) || lmin <= 0.0) invalid = 1;
            if (!isfinite(s) || s <= 0.0) invalid = 1;
        }
        if (wa_config.release_cycles < 1U || wa_config.release_cycles > 20U) invalid = 1;
        if (wa_config.restore_cycles < 1U || wa_config.restore_cycles > 20U) invalid = 1;
    }

    if (!invalid) {
        for (i = 0; i < 3; i++) {
            if (adcs_vec3_normalize(&wa_input.axes[i], ADCS_EPS_NORM, &axes_norm[i]) != ADCS_OK) {
                invalid = 1;
                break;
            }
        }
    }

    if (!invalid) {
        int j;
        for (i = 0; i < 3; i++) {
            for (j = i + 1; j < 3; j++) {
                double d = adcs_vec3_dot(&axes_norm[i], &axes_norm[j]);
                if (fabs(d) > 1.0e-6) { invalid = 1; break; }
            }
            if (invalid) break;
        }
    }

    if (invalid) {
        wa_state.mode = WA_FAULT;
        wa_output.mode = WA_FAULT;
        wa_output.clean_count = 0U;
        wa_output.restore_count = 0U;
        wa_output.saturation_mask = 0U;
        wa_output.slew_mask = 0U;
        wa_output.unavailable_mask = 7U;
        for (i = 0; i < 3; i++) {
            wa_output.wheel_torque_nm[i] = 0.0;
            wa_state.previous_wheel_torque_nm[i] = 0.0;
        }
        wa_output.achieved_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        wa_output.residual_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        wa_output.residual_norm_nm = 0.0;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
        return;
    }

    if (!wa_input.enable) {
        wa_state.mode = WA_NORMAL;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
        for (i = 0; i < 3; i++) {
            wa_state.previous_wheel_torque_nm[i] = 0.0;
            wa_output.wheel_torque_nm[i] = 0.0;
        }
        wa_output.mode = WA_NORMAL;
        wa_output.clean_count = 0U;
        wa_output.restore_count = 0U;
        wa_output.saturation_mask = 0U;
        wa_output.slew_mask = 0U;
        wa_output.unavailable_mask = (~wa_input.available_mask) & 7U;
        wa_output.achieved_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        wa_output.residual_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        wa_output.residual_norm_nm = 0.0;
        return;
    }

    for (i = 0; i < 3; i++) {
        usable[i] = ((wa_input.available_mask >> i) & 1U) ? 1 : 0;
        if (!usable[i]) {
            new_unavail |= (uint32_t)(1U << i);
        } else {
