            continue;
        }
        desired = -adcs_vec3_dot(&axes_norm[i], wa_input.requested_torque_nm);

        mag_limited = desired;
        if (fabs(mag_limited) > wa_config.wheel_limit_nm[i]) {
            mag_limited = copysign(wa_config.wheel_limit_nm[i], mag_limited);
            new_sat |= (uint32_t)(1U << i);
        }

        cmd = mag_limited;
        delta = cmd - wa_state.previous_wheel_torque_nm[i];
        slew = wa_config.max_wheel_slew_nm_per_cycle[i];
        if (fabs(delta) > slew) {
            cmd = wa_state.previous_wheel_torque_nm[i] + copysign(slew, delta);
            new_slew |= (uint32_t)(1U << i);
        }

        wa_output.wheel_torque_nm[i] = cmd;
    }

    {
        adcs_vec3_t acc = {0.0, 0.0, 0.0};
        for (i = 0; i < 3; i++) {
            adcs_vec3_t term = adcs_vec3_scale(&axes_norm[i], wa_output.wheel_torque_nm[i]);
            acc = adcs_vec3_add(&acc, &term);
        }
        achieved = acc;
    }

    wa_output.achieved_torque_nm = achieved;
    wa_output.residual_torque_nm = adcs_vec3_sub(wa_input.requested_torque_nm, &achieved);
    wa_output.residual_norm_nm = adcs_vec3_norm(&wa_output.residual_torque_nm);
    wa_output.saturation_mask = new_sat;
    wa_output.slew_mask = new_slew;
    wa_output.unavailable_mask = new_unavail;

    any_limited = ((new_sat != 0U) || (new_slew != 0U)) ? 1 : 0;

    if (any_limited) {
        wa_state.mode = WA_LIMITED;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
    } else if (new_unavail != 0U) {
        wa_state.mode = WA_DEGRADED;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
    } else if (wa_state.mode == WA_LIMITED) {
        wa_state.clean_count++;
        if (wa_state.clean_count >= wa_config.release_cycles) {
            wa_state.mode = WA_RECOVERING;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
        }
    } else if (wa_state.mode == WA_DEGRADED) {
        wa_state.mode = WA_RECOVERING;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
    } else if (wa_state.mode == WA_RECOVERING) {
        wa_state.restore_count++;
        if (wa_state.restore_count >= wa_config.restore_cycles) {
            wa_state.mode = WA_NORMAL;
            wa_state.restore_count = 0U;
            wa_state.clean_count = 0U;
        }
    } else {
        wa_state.mode = WA_NORMAL;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
    }

    for (i = 0; i < 3; i++) {
        wa_state.previous_wheel_torque_nm[i] = wa_output.wheel_torque_nm[i];
    }

    wa_output.mode = wa_state.mode;
    wa_output.clean_count = wa_state.clean_count;
    wa_output.restore_count = wa_state.restore_count;
    return;
}

