static void wa_state_step(unint32 avail_count, int have_unavail)
{
    int limited_now;

    if (avail_count < 2U) {
        wa_fault_reset();
        return;
    }

    limited_now = (wa_output.saturation_mask != 0U) || (wa_output.slew_mask != 0U);

    if (limited_now) {
        /* limit events take precedence over health recovery */
        wa_state.mode = WA_LIMITED;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
    } else if (have_unavail) {
        wa_state.mode = WA_DEGRADED;
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
    } else {
        /* all three wheels available and no limit event */
        switch (wa_state.mode) {
        case WA_FAULT:
            wa_state.mode = WA_RECOVERING;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 1U;
            break;
        case WA_NORMAL:
            wa_state.clean_count = 0U;
            wa_state.restore_count = 0U;
            break;
        case WA_LIMITED:
            if (wa_state.clean_count < wa_config.release_cycles) {
                wa_state.clean_count += 1U;
            }
            if (wa_state.clean_count >= wa_config.release_cycles) {
                wa_state.mode = WA_NORMAL;
                wa_state.clean_count = 0U;
                wa_state.restore_count = 0U;
            }
            break;
        case WA_DEGRADED:
            wa_state.mode = WA_RECOVERING;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 1U;
            break;
        case WA_RECOVERING:
            if (wa_state.restore_count < wa_config.restore_cycles) {
                wa_state.restore_count += 1U;
            }
            if (wa_state.restore_count >= wa_config.restore_cycles) {
                wa_state.mode = WA_NORMAL;
                wa_state.clean_count = 0U;
                wa_state.restore_count = 0U;
            }
            break;
        default:
            wa_state.mode = WA_RECOVERING;
            wa_state.clean_count = 0U;
            wa_state.restore_count = 1U;
            break;
        }
    }

    wa_output.mode = wa_state.mode;
    wa_output.clean_count = wa_state.clean_count;
    wa_output.restore_count = wa_state.restore_count;
}

void GncRepoWheelAllocateStep(void)
{
    adcs_vec3_t axes_n[3];
    adcs_vec3_t req;
    adcs_vec3_t achieved = {0.0, 0.0, 0.0};
    adcs_vec3_t residual;
    unint32 avail_count = 0U;
    unint32 i;
    int have_unavail = 0;

    if (wa_input.enable == 0) {
        wa_zero_outputs();
        wa_output.mode = WA_NORMAL;
        wa_output.clean_count = 0U;
        wa_output.restore_count = 0U;
        for (i = 0U; i < 3U; i++) {
            wa_state.previous_wheel_torque_nm[i] = 0.0;
        }
        wa_state.clean_count = 0U;
        wa_state.restore_count = 0U;
        wa_state.mode = WA_NORMAL;
        return;
    }

    if (wa_input.axis_count != 3U) {
        wa_fault_reset();
        return;
    }
    if ((wa_input.axes == NULL) || (wa_input.requested_torque_nm == NULL)) {
        wa_fault_reset();
        return;
    }
    if ((wa_input.available_mask & ~0x7U) != 0U) {
        wa_fault_reset();
        return;
    }
    if (!wa_is_finite3v(wa_input.requested_torque_nm)) {
        wa_fault_reset();
        return;
    }
    if (!wa_config_valid()) {
        wa_fault_reset();
        return;
    }
    if (!wa_axes_orthonormal_valid(wa_input.axes, axes_n)) {
        wa_fault_reset();
        return;
    }

    for (i = 0U; i < 3U; i++) {
        if ((wa_input.available_mask & (unint32)(1U << i)) != 0U) {
            avail_count++;
        } else {
            have_unavail = 1;
        }
    }
    if (avail_count < 2U) {
        wa_fault_reset();
        return;
    }

    req = *wa_input.requested_torque_nm;

    wa_output.saturation_mask = 0U;
    wa_output.slew_mask = 0U;
    wa_output.unavailable_mask = 0U;
    for (i = 0U; i < 3U; i++) {
        if ((wa_input.available_mask & (unint32)(1U << i)) == 0U) {
            wa_output.wheel_torque_nm[i] = 0.0;
            wa_output.unavailable_mask |= (unint32)(1U << i);
        } else {
            double desired = adcs_vec3_dot(&axes_n[i], &req);
            double limited = desired;
            double prev;
            double delta;

            if (desired > wa_config.wheel_limit_nm[i]) {
                limited = wa_config.wheel_limit_nm[i];
                wa_output.saturation_mask |= (unint32)(1U << i);
            } else if (desired < -wa_config.wheel_limit_nm[i]) {
                limited = -wa_config.wheel_limit_nm[i];
                wa_output.saturation_mask |= (unint32)(1U << i);
            }

            prev = wa_state.previous_wheel_torque_nm[i];
            delta = limited - prev;

            if (delta > wa_config.max_wheel_slew_nm_per_cycle[i]) {
                limited = prev + wa_config.max_wheel_slew_nm_per_cycle[i];
                wa_output.slew_mask |= (unint32)(1U << i);
            } else if (delta < -wa_config.max_wheel_slew_nm_per_cycle[i]) {
                limited = prev - wa_config.max_wheel_slew_nm_per_cycle[i];
                wa_output.slew_mask |= (unint32)(1U << i);
            }

            wa_output.wheel_torque_nm[i] = limited;
        }
    }

    for (i = 0U; i < 3U; i++) {
        if ((wa_input.available_mask & (unint32)(1U << i)) != 0U) {
            adcs_vec3_t term = adcs_vec3_scale(&axes_n[i], wa_output.wheel_torque_nm[i]);
            achieved = adcs_vec3_add(&achieved, &term);
        }
    }
    wa_output.achieved_torque_nm = achieved;
    residual = adcs_vec3_sub(&req, &achieved);
    wa_output.residual_torque_nm = residual;
    wa_output.residual_norm_nm = adcs_vec3_norm(&residual);

    for (i = 0U; i < 3U; i++) {
        wa_state.previous_wheel_torque_nm[i] = wa_output.wheel_torque_nm[i];
    }

    wa_state_step(avail_count, have_unavail);
}

